    @Test
    void twoPendingRainsRacingToEffectiveProduceExactlyOne() throws Exception {
        long windowId = createWindow("ch-rain-race-" + run, "10");
        String r1 = registerRain(windowId, "4", "2026-10-01T00:10:00Z", "clerk");
